    VISCOSITY_OK : BOOL;
    PASTE_E_STOP_NC : BOOL;
    DebounceTime : TIME;
    CycleTime : TIME;


END_VAR

VAR_OUTPUT
    VFD_RUN : BOOL := FALSE;
    PUMP_MAINT_DUE : BOOL := FALSE;
    PUMP_RUNTIME_ACC : LTIME := LTIME#0s;
END_VAR

VAR
    viscosityTimer : TON;
    viscosityValid : BOOL := FALSE;
    tmpCycleMs : LINT;
    tmpAccMs : LINT;
END_VAR

// Engineering Contract:
// - VFD_RUN: activation=VISCOSITY_OK TRUE for DebounceTime AND PASTE_E_STOP_NC TRUE, 
//            retention=held while conditions maintained, reset=immediate on E-stop or viscosity invalid
// - PUMP_MAINT_DUE: set when accumulated runtime >= 500 hours, informational only
// - PUMP_RUNTIME_ACC: accumulates while VFD_RUN TRUE, preserves when stopped

